import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"路易·布鲁姆金","description":"","frontmatter":{"title":"路易·布鲁姆金","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/路易·布鲁姆金.md","filePath":"04_people/路易·布鲁姆金.md"}'),o={name:"04_people/路易·布鲁姆金.md"};function i(s,a,n,_,h,p){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="路易·布鲁姆金" tabindex="-1">路易·布鲁姆金 <a class="header-anchor" href="#路易·布鲁姆金" aria-label="Permalink to &quot;路易·布鲁姆金&quot;">​</a></h1><ul><li><strong>角色职位</strong>：内布拉斯加家具城（NFM）管理者</li><li><strong>与巴菲特关系</strong>：B夫人（罗斯·布鲁姆金）之子，NFM家族传承的关键人物</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>路易·布鲁姆金是传奇零售巨头——内布拉斯加家具城（Nebraska Furniture Mart，简称NFM）创始人B夫人（罗斯·布鲁姆金）的儿子。在母亲的培养和引导下，路易·布鲁姆金逐步成长为NFM的核心管理者，延续了这一家族零售传奇。</p><p>路易从小在NFM的柜台边长大，亲眼见证了母亲白手起家的过程。NFM从一家小型家具店发展成为内布拉斯加州最大的家具零售商，并成为伯克希尔·哈撒韦旗下重要的零售业务板块。路易在母亲退休或过世后，承担起了延续NFM辉煌的使命。</p><p>路易·布鲁姆金忠诚地继承了母亲&quot;薄利多销、童叟无欺&quot;的经营理念，保持了NFM在奥马哈家具市场的绝对领先地位。他与巴菲特保持着良好的信任关系，延续了B夫人与巴菲特建立的合作传统，使NFM继续为伯克希尔贡献稳定且可观的利润。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1980年代以前</strong>：在NFM从基层做起，逐步学习零售业务</li><li><strong>B夫人退休后</strong>：接任NFM管理职务，确保公司平稳过渡</li><li><strong>延续至今</strong>：继续领导NFM，延续家族零售传奇</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=NFM%2F内布拉斯加家具城">1983年：完整翻译|/01_letters/1983年/翻译</a></li><li><a href="/search?q=NFM%2F内布拉斯加家具城">1985年：完整翻译|/01_letters/1985年/翻译</a></li><li><a href="/search?q=NFM%2F内布拉斯加家具城">2020年：完整翻译|/01_letters/2020年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{d as __pageData,u as default};
